:root {
    --primary-color: #25949c;
    --btn-maroon-dark: #1d777d;
    --heading-color: #000000;
    --text-color: #000000;
    --white: #ffffff;
    --border-color: #eeeeee;
    --font-family: 'Poppins', sans-serif;
    --transition: all 0.25s ease;
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    padding: 0;
    font-family: var(--font-family);
    color: var(--text-color);
    background-color: var(--white);
    -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6, p, label, li {
    color: var(--heading-color);
}

a {
    transition: var(--transition);
}

.header-top {
    width: 100%;
    background-color: var(--white);
    border-bottom: 1px solid var(--border-color);
}

.header-top-inner {
    min-height: 84px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 15px 30px;
    padding: 14px 0;
}

.header-contact {
    display: flex;
    align-items: center;
    gap: 48px;
}

.header-contact .contact-item {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    color: #1f1f1f;
    text-decoration: none;
}

.header-contact .contact-item i {
    font-size: 26px;
    line-height: 1;
}

.header-contact .contact-info {
    display: flex;
    flex-direction: column;
    line-height: 1.25;
}

.header-contact .contact-info strong {
    font-size: 14px;
    font-weight: 400;
    white-space: nowrap;
}

.header-contact .contact-info small {
    color: #7a7a7a;
    font-size: 15px;
}

.header-contact .contact-item:hover i, .header-contact .contact-item:hover strong {
    color: var(--primary-color);
}

.site-header {
    position: sticky;
    top: 0;
    z-index: 1050;
    background-color: var(--white);
}

.site-header .navbar {
    min-height: 84px;
    padding: 8px 0;
    background-color: #87ceeb0d;
}

.site-header .site-logo {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    padding: 0;
    text-decoration: none;
}

.site-header .site-logo-img {
    display: block;
    height: 58px;
    object-fit: contain;
    flex-shrink: 0;
}

.site-header .logo-text {
    display: flex;
    flex-direction: column;
    line-height: 1.15;
}

.site-header .logo-name {
    color: var(--primary-color);
    font-size: 16px;
    font-weight: 700;
    letter-spacing: 0.2px;
    white-space: nowrap;
}

.site-header .logo-tagline {
    margin-top: 3px;
    color: #7a7a7a;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.3px;
    white-space: nowrap;
}

.site-header .navbar-nav {
    flex-direction: row;
    align-items: center;
    gap: 3px;
    width: 100%;
}

.site-header .nav-link {
    position: relative;
    padding: 14px 11px !important;
    color: #1a1a1a;
    font-size: 15px;
    white-space: nowrap;
    transition: var(--transition);
}

.site-header .nav-link:hover, .site-header .nav-link:focus, .site-header .nav-link.active {
    color: var(--primary-color);
}

.site-header .navbar-nav .nav-item:last-child {
    margin-left: auto !important;
}

.site-header .appointment-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 8px 16px;
    color: #ffffff;
    background-color: var(--primary-color);
    border: 1px solid var(--primary-color);
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
    transition: var(--transition);
}

.site-header .appointment-btn:hover, .site-header .appointment-btn:focus {
    /* color: var(--primary-color); */
    background-color: var(--btn-maroon-dark);
    border-color: var(--btn-maroon-dark);
    transform: translateY(-2px);
}

.home-banner {
    position: relative;
    width: 100%;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

.home-banner img {
    display: block;
    width: 100%;
    height: auto;
    object-fit: cover;
}

.about-doctor-section {
    background-color: var(--white);
    margin: 34px;
}

.about-doctor-section.container {
    margin-top: 34px;
    margin-bottom: 34px;
    margin-inline: auto; }

.about-doctor-section .about-row {
    display: flex;
    align-items: flex-start;
    gap: 45px;
    background: #87ceeb0d;
}

/* Left Side */
.about-doctor-section .about-left {
    flex: 1 1 62%;
    max-width: 62%;
    padding-top: 10px;
}

/* section-tag (padding: 10px) aur section-text (margin: 10px) ke left edge
   ke sath title ko bhi vertically align karo - 10px spacing same rakho */
.about-doctor-section .about-left .section-title {
    margin: 10px;
}

/* Reusable paragraph class - kisi bhi section me lagao, UI same rahega */
.section-text {
    color: #1a1a1a;
    font-size: 16px;
    font-weight: 400;
    margin: 10px;
}

.about-doctor-section .about-actions {
    display: flex;
    align-items: center;
    gap: 45px;
}

.about-doctor-section .about-btn, .pregnancy-care-section .about-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 132px;
    padding: 6px 30px;
    color: #ffffff;
    background-color: var( --primary-color);
    border: 1px solid var( --primary-color);
    border-radius: 40px;
    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 600;
    text-decoration: none;
    cursor: pointer;
    transition: var(--transition);
}

.about-doctor-section .about-btn:hover, .about-doctor-section .about-btn:focus, .pregnancy-care-section .about-btn:hover, .pregnancy-care-section .about-btn:focus {
    color: #ffffff;
    background-color: var( --primary-color);
    border-color: var( --primary-color);
}

.about-doctor-section .about-helpline {
    color: #000000;
    font-size: 22px;
    font-weight: 400;
    text-decoration: none;
    white-space: nowrap;
    transition: var(--transition);
}

.about-doctor-section .about-helpline:hover {
    color: var( --primary-color);
}

/* Right Side Image */
.about-doctor-section .why-choose {
    flex: 1 1 34%;
    max-width: 34%;
}

.about-doctor-section .why-choose img {
    display: block;
    width: 100%;
    height: 500px;
}

.gallery-section {
    width: 100%;
    background-color: var(--white);
    margin: 40px;
}

/* Container wale gallery section me left/right auto margin restore karo -
   warna margin: 40px Bootstrap ke margin-inline: auto ko override kar deta
   hai aur left/right space unequal ho jata hai */
.gallery-section.container {
    margin-top: 40px;
    margin-bottom: 40px;
    margin-inline: auto; }

.section-head {
    max-width: 1100px;
    margin: 0 auto 30px;
    padding: 0 20px;
    text-align: center;
}

.section-tag {
    display: block;
    margin-bottom: -1px;
    color: var(--primary-color);
    font-size: 16px;
    font-weight: 700;
    padding: 10px;
}

.section-title {
    margin: 0;
    color: #000000;
    font-size: 25px;
    font-weight: 600;
    line-height: 1.3;
}

.gallery-section .gallery-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.gallery-section .gallery-item {
    overflow: hidden;
    border-radius: 14px;
}

.gallery-section .gallery-item img {
    display: block;
    width: 100%;
    height: 330px;
    object-fit: cover;
    transition: var(--transition);
}

.gallery-section .gallery-item:hover img {
    transform: scale(1.06);
}

.conditions-section .condition-card {
    height: 100%;
    background-color: var(--white);
    border: 1px solid #e9e9e9;
    border-radius: 12px;
    text-align: center;
    transition: var(--transition);
    overflow: hidden;
}

.conditions-section a.condition-card {
    display: block;
    text-decoration: none;
    color: inherit;
}

.conditions-section .condition-card img {
    display: block;
    width: 100%;
    height: 200px;
    margin: 0 auto 18px;
    object-fit: cover;
    object-position: center;
}

.conditions-section .condition-name {
    margin: 0 12px 12px;
    color: #000000;
    font-size: 15px;
    font-weight: 550;
    line-height: 1.4;
}

.conditions-section .condition-text {
    margin: 0 12px 18px;
    color: #333333;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.5;
}

.conditions-section .condition-card:hover {
    border-color: var(--primary-color);
    transform: translateY(-4px);
}

/* Symptoms List Item */
.symptom-item {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 20px;
}

.symptom-item i {
    flex-shrink: 0;
    color: var(--primary-color);
}

.symptom-item:last-child {
    margin-bottom: 0;
}

.commitment-section .about-row {
    align-items: center;
}

.commitment-section .commitment-image {
    flex: 1 1 38%;
    max-width: 38%;
}

.commitment-section .commitment-image img {
    display: block;
    width: 80%;
    height: auto;
}

.commitment-section .about-left {
    flex: 1 1 56%;
    max-width: 56%;
}

.appointment-section {
    margin-inline: 0;
    padding-bottom: 60px;
    padding-top: 80px;
    /* padding-left: 130px; */
    background: linear-gradient(rgb(37 148 156 / 38%), rgba(37, 148, 156, 0.88)), url(../assets/book-appointment.webp) center / cover no-repeat;
}

/* Schedule Consultation Section (Clinic / Hospital info + Appointment form) */
.consult-section {

    width: 100%;
    padding: 40px;
    background-color: #87ceeb0d;
}

.consult-section .section-title {
    margin-bottom: 45px;
}

/* Clinic / Hospital Tabs */
.consult-section .consult-tabs {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    /* padding: 7px; */
    background-color: #f1f1f4;
    border-radius: 999px;
}

.consult-section .consult-tab {
    padding: 13px 34px;
    border: 0;
    border-radius: 999px;
    background-color: transparent;
    color: var(--primary-color);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 600;
    line-height: 1;
    cursor: pointer;
    transition: var(--transition);
}

.consult-section .consult-tab:hover {
    color: var(--primary-color);
}

.consult-section .consult-tab.active, .consult-section .consult-tab.active:hover {
    background-color: var(--primary-color);
    color: #ffffff;
    font-size: 16px;
}

/* Contact List */
.consult-section .consult-list {
    margin: 36px 0 30px;
    padding: 0;
    list-style: none;
}

.consult-section .consult-item {
    display: flex;
    align-items: center;
    gap: 22px;
    margin-bottom: 26px;
}

.consult-section .consult-item:last-child {
    margin-bottom: 0;
}

.consult-section .consult-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 58px;
    height: 58px;
    border-radius: 50%;
    background-color: var(--white);
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
    color: var(--primary-color);
    font-size: 22px;
}

.consult-section .consult-detail {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.consult-section .consult-label {
    color: #111111;
    font-size: 17px;
    font-weight: 500;
}

.consult-section .consult-value {
    color: #000000;
    font-size: 16px;
    /* font-weight: 70; */
    text-decoration: none;
}

a.consult-section .consult-value:hover {
    color: var(--primary-color);
}

/* Location Button */
.consult-section .consult-branch {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 28px;
    padding: 11px 34px;
    border: 0;
    border-radius: 8px;
    background-color: var(--primary-color);
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
}

.consult-section .consult-branch:hover, .consult-section .consult-branch:focus {
    background-color: var(--primary-color);
    transform: translateY(-2px);
}

/* Google Map */
.consult-section .consult-map {
    position: relative;
    border-radius: 14px;
    overflow: hidden;
}

.consult-section .consult-map iframe {
    display: block;
    width: 100%;
    height: 260px;
    border: 0;
}

.consult-section .consult-map-address {
    position: absolute;
    bottom: 12px;
    left: 12px;
    z-index: 2;
    max-width: calc(100% - 48px);
    padding: 10px 14px;
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
    color: #202124;
    font-size: 14px;
    font-weight: 600;
}

/* Appointment Form Card */
.consult-section .consult-form-card {
    padding: 38px 34px;
    background-color: var(--white);
    border: 1px solid #f0f0f0;
    border-radius: 16px;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.08);
}

.consult-section .consult-field {
    margin-bottom: 22px;
}

.consult-section .consult-field label {
    display: block;
    margin-bottom: 10px;
    color: #111111;
    font-size: 15px;
    font-weight: 500;
}

.consult-section .consult-input-wrap {
    position: relative;
}

.consult-section .consult-input-wrap > i {
    position: absolute;
    top: 50%;
    left: 18px;
    transform: translateY(-50%);
    color: #8a8a8a;
    font-size: 18px;
    pointer-events: none;
}

.consult-section .consult-input-wrap.consult-input-area > i {
    top: 20px;
    transform: none;
}

.consult-section .consult-input {
    display: block;
    width: 100%;
    padding: 16px 18px 16px 50px;
    border: 1px solid #e6e6e6;
    border-radius: 10px;
    background-color: var(--white);
    color: #111111;
    font-family: var(--font-family);
    font-size: 16px;
    outline: none;
    transition: var(--transition);
}

.consult-section .consult-input::placeholder {
    color: #9a9a9a;
}

.consult-section .consult-input:focus {
    border-color: var(--consult-maroon);
    box-shadow: 0 0 0 3px rgba(125, 31, 65, 0.12);
}

.consult-section textarea.consult-input {
    min-height: 130px;
    resize: vertical;
}

/* Submit Button + Message */
.consult-section .consult-submit {
    display: block;
    width: 50%;
    padding: 12px;
    border: 0;
    border-radius: 10px;
    background-color: var(--primary-color);
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
}

.consult-section .consult-submit:hover, .consult-section .consult-submit:focus {
    background-color: var(--primary-color);
    transform: translateY(-2px);
}

/* Patient Testimonials */
.testimonials-section {
    padding: 60px 0;
    background: #25949c0a;
}

.testimonials-flex {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: stretch;
    gap: 24px;
}

.testimonial-card {
    flex: 1 1 300px;
    max-width: 360px;
    padding: 28px 24px;
    background: #ffffff;
    border: 1px solid #e8e8e8;
    border-radius: 10px;
    display: flex;
    flex-direction: column;
}

.testimonial-stars {
    color: #f5a623;
    font-size: 22px;
    letter-spacing: 3px;
    margin-bottom: 12px;
}

.testimonial-heading {
    font-size: 15px;
    font-weight: 600;
    margin-bottom: 12px;
    color: #000000;
}

.testimonial-name {
    margin-top: auto;
    padding-top: 18px;
    font-size: 16px;
    font-weight: 600;
    color: var(--primary-color);
}

.site-footer {
    background: #25949c;
    color: #ffffff;
    padding: 50px 0 0;
    font-family: 'Poppins', sans-serif;
}

.site-footer .container {
    max-width: 1200px;
}

.site-footer .row {
    row-gap: 35px;
}

.site-footer h3 {
    color: #ffffff;
    font-size: 20px;
    font-weight: 600;
    margin-bottom: 22px;
    line-height: 1.4;
}

.site-footer p {
    color: #d5e0e1;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.9;
    /* margin-bottom: 16px; */
}

.site-footer ul {
    padding: 0;
    margin: 0;
}

.site-footer ul li {
    color: #d5e0e1;
    font-size: 14px;
    line-height: 1.8;
    margin-bottom: 10px;
}

.site-footer a {
    color: #d5e0e1;
    text-decoration: none;
    transition: color 0.3s ease;
}

.site-footer ul li a {
    display: inline-block;
}

.site-footer a:hover {
    color: #25949c;
}

.site-footer strong {
    color: #ffffff;
    font-weight: 600;
}

.site-footer hr {
    border: 0;
    border-top: 1px solid rgba(255, 255, 255, 0.2);
    margin: 35px 0 0;
    opacity: 1;
}

.site-footer .footer-bottom {
    padding: 20px 0;
}

.site-footer .footer-bottom p {
    margin: 0;
    font-size: 13px;
    color: #d5e0e1;
}

/* Appointment Link */
.site-footer a[href*="appointment.php"] {
    display: inline-block;
    margin-top: 8px;
    padding: 11px 18px;
    background: #ffffff;
    color: #102d32;
    border-radius: 5px;
    font-size: 13px;
    font-weight: 600;
}

.site-footer a[href*="appointment.php"]:hover {
    background: #25949c;
    color: #102d32;
}

/* Footer Doctor Logo and Branding */
.site-footer .footer-doctor-brand {
    margin-bottom: 22px;
}

.site-footer .footer-doctor-logo {
    display: block;
    width: 95px;
    margin-bottom: 12px;
}

.site-footer .footer-doctor-logo img {
    display: block;
    width: 100%;
    height: 75px;
    object-fit: contain;
    object-position: left center;
}

.site-footer .footer-doctor-name {
    margin-bottom: 6px;
    font-size: 21px;
    font-weight: 600;
    line-height: 1.4;
}

.site-footer .footer-doctor-brand p {
    /* margin-bottom: 12px; */
}

/* Footer Social Media Icons */
.site-footer .footer-social-icons {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
}

.site-footer .footer-social-icons a {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    border: 1px solid rgba(255, 255, 255, 0.35);
    border-radius: 50%;
    color: #ffffff;
    font-size: 19px;
    transition: background 0.3s ease, color 0.3s ease, transform 0.3s ease;
}

.site-footer .footer-social-icons a:hover {
    background: #ffffff;
    color: #102d32;
    transform: translateY(-3px);
